Clase Termometro
    Privado Definir celsius Como Entero;

    Metodo Constructor(unCelsius Como Entero)
        Este.celsius <- unCelsius;
    FinMetodo

    Publico Metodo Fahrenheit() Como Real
        Retornar Este.celsius * 9 / 5 + 32;
    FinMetodo
FinClase

Proceso ConvertirTemperatura
    Definir celsius Como Entero;
    Definir termometro Como Termometro;
    Leer celsius;
    termometro <- Nuevo Termometro(celsius);
    Escribir termometro.Fahrenheit();
FinProceso
